//go:build s390x

package floats

// Vector-facility Maximum and Minimum kernels (maxmin.go; z13 baseline, so no
// runtime gate), generated by go-asmgen (maxmin_s390x_gen.go) into
// maxmin_s390x.s. A kernel does the whole blocks of eight elements; the Go code
// finishes the last seven with the scalar rule.
//
//go:noescape
func maximumVX(dst, a, b *float64, n int)

//go:noescape
func minimumVX(dst, a, b *float64, n int)

func vmaximum(dst, a, b []float64) {
	if n := len(a) &^ 7; n > 0 {
		maximumVX(&dst[0], &a[0], &b[0], n)
		dst, a, b = dst[n:], a[n:], b[n:]
	}
	maximumRule(dst, a, b)
}

func vminimum(dst, a, b []float64) {
	if n := len(a) &^ 7; n > 0 {
		minimumVX(&dst[0], &a[0], &b[0], n)
		dst, a, b = dst[n:], a[n:], b[n:]
	}
	minimumRule(dst, a, b)
}
